34	#[ORM\Entity]
35	#[ORM\Table(name: 'orders')]
36	final class Order extends AggregateRoot
37	{
38	    /** @var Collection<int, OrderItem> */
39	    #[ORM\OneToMany(targetEntity: OrderItem::class, mappedBy: 'order', cascade: ['persist'], orphanRemoval: true)]
40	    private Collection $lines;
41	
42	    /**
43	     * Položky jen ke čtení: vrací se kopie, přidává se přes addItem().
44	     *
45	     * @var list<OrderItem>
46	     */
47	    public array $items {
48	        get => array_values($this->lines->toArray());
49	    }
50	
51	    // Asymetrická viditelnost: přečte kdokoli, zapíše jen kód uvnitř třídy.
52	    #[ORM\Column(enumType: OrderStatus::class)]
53	    public private(set) OrderStatus $status;
54	
55	    #[ORM\Column(nullable: true)]
56	    public private(set) ?\DateTimeImmutable $placedAt = null;
57	
58	    // Důvod storna.
59	    #[ORM\Column(type: 'text', nullable: true)]
60	    public private(set) ?string $cancellationNote = null;
61	
62	    // Sleva na celou objednávku. Kniha ji nemá, kurz ano (viz README).
63	    #[ORM\Embedded(class: Money::class, columnPrefix: 'discount_')]
64	    public private(set) Money $discount;
65	
66	    private function __construct(
67	        #[ORM\Id]
68	        #[ORM\Column(type: 'order_id')]
69	        public readonly OrderId $id,
70	        #[ORM\Column(type: 'customer_id')]
71	        public readonly CustomerId $customerId,
72	        #[ORM\Column(enumType: Currency::class)]
73	        public readonly Currency $currency,
74	    ) {
75	        $this->status = OrderStatus::Draft;
76	        $this->lines = new ArrayCollection();
77	        $this->discount = Money::zero($currency);
78	    }
79	
80	    public static function place(OrderId $id, CustomerId $customerId, Currency $currency = Currency::CZK): self
81	    {
82	        $order = new self($id, $customerId, $currency);
83	        $order->record(new OrderPlaced($id, $customerId, new \DateTimeImmutable()));
84	
85	        return $order;
86	    }
87	
88	    public function addItem(ProductId $productId, int $quantity, Money $unitPrice): void
89	    {
90	        if ($this->status !== OrderStatus::Draft) {
91	            throw InvalidOrderStateTransitionException::notAllowedInState('addItem', $this->status->value);
92	        }
93	
94	        $this->assertSameCurrency($unitPrice);
95	
96	        // Jedna položka na produkt: množství se sčítá, položka se neduplikuje.
97	        foreach ($this->lines as $existing) {
98	            if ($existing->productId->equals($productId)) {
99	                $existing->increaseQuantity($quantity);
100	                $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
101	
102	                return;
103	            }
104	        }
105	
106	        $this->lines->add(new OrderItem($this, $productId, $quantity, $unitPrice));
107	        $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
108	    }
109	
110	    public function changeItemQuantity(ProductId $productId, int $quantity): void
111	    {
112	        if ($this->status !== OrderStatus::Draft) {
113	            throw InvalidOrderStateTransitionException::notAllowedInState('changeItemQuantity', $this->status->value);
114	        }
115	
116	        if ($quantity < 1) {
117	            throw InvalidQuantityException::mustBePositive($quantity);
118	        }
119	
120	        $this->itemFor($productId)->changeQuantity($quantity);
121	        $this->record(new OrderItemQuantityChanged($this->id, $productId, $quantity, new \DateTimeImmutable()));
122	    }
123	
124	    public function removeItem(ProductId $productId): void
125	    {
126	        if ($this->status !== OrderStatus::Draft) {
127	            throw InvalidOrderStateTransitionException::notAllowedInState('removeItem', $this->status->value);
128	        }
129	
130	        $item = $this->itemFor($productId);
131	        if ($this->lines->count() === 1) {
132	            throw LastItemCannotBeRemovedException::forProduct($productId);
133	        }
134	
135	        // Sleva nesmí po odebrání přesáhnout nový součet položek.
136	        $newTotal = $this->totalAmount()->subtract($item->subtotal());
137	        if ($this->discount->amountInCents > $newTotal->amountInCents) {
138	            throw DiscountExceedsItemsTotalException::forItemsTotal($this->discount, $newTotal);
139	        }
140	
141	        $this->lines->removeElement($item);
142	        $this->record(new OrderItemRemoved($this->id, $productId, new \DateTimeImmutable()));
143	    }
144	
145	    public function applyDiscount(Money $discount): void
146	    {
147	        if ($this->status !== OrderStatus::Draft) {
148	            throw InvalidOrderStateTransitionException::notAllowedInState('applyDiscount', $this->status->value);
149	        }
150	
151	        $this->assertSameCurrency($discount);
152	
153	        $total = $this->totalAmount();
154	        if ($discount->amountInCents > $total->amountInCents) {
155	            throw DiscountExceedsItemsTotalException::forItemsTotal($discount, $total);
156	        }
157	
158	        $this->discount = $discount;
159	    }
160	
161	    public function confirm(?\DateTimeImmutable $at = null): void
162	    {
163	        if (!$this->status->canTransitionTo(OrderStatus::Confirmed)) {
164	            throw InvalidOrderStateTransitionException::cannotTransition(
165	                $this->status->value,
166	                OrderStatus::Confirmed->value,
167	            );
168	        }
169	
170	        if ($this->lines->isEmpty()) {
171	            throw EmptyOrderException::cannotConfirm();
172	        }
173	
174	        $this->status = OrderStatus::Confirmed;
175	        $this->placedAt = $at ?? new \DateTimeImmutable();
176	        $this->record(new OrderConfirmed($this->id, $this->customerId, $this->placedAt));
177	    }
178	
179	    public function markPaid(): void
180	    {
181	        // Opakované doručení příkazu o platbě není chyba volajícího.
182	        if ($this->status === OrderStatus::Paid) {
183	            return;
184	        }
185	
186	        if (!$this->status->canTransitionTo(OrderStatus::Paid)) {
187	            throw InvalidOrderStateTransitionException::cannotTransition(
188	                $this->status->value,
189	                OrderStatus::Paid->value,
190	            );
191	        }
192	
193	        $this->status = OrderStatus::Paid;
194	        $this->record(new OrderPaid($this->id, new \DateTimeImmutable()));
195	    }
196	
197	    public function ship(): void
198	    {
199	        if ($this->status === OrderStatus::Shipped) {
200	            return;
201	        }
202	
203	        if (!$this->status->canTransitionTo(OrderStatus::Shipped)) {
204	            throw InvalidOrderStateTransitionException::cannotTransition(
205	                $this->status->value,
206	                OrderStatus::Shipped->value,
207	            );
208	        }
209	
210	        $this->status = OrderStatus::Shipped;
211	        $this->record(new OrderShipped($this->id, new \DateTimeImmutable()));
212	    }
213	
214	    public function deliver(): void
215	    {
216	        if (!$this->status->canTransitionTo(OrderStatus::Delivered)) {
217	            throw InvalidOrderStateTransitionException::cannotTransition(
218	                $this->status->value,
219	                OrderStatus::Delivered->value,
220	            );
221	        }
222	
223	        $this->status = OrderStatus::Delivered;
224	        $this->record(new OrderDelivered($this->id, new \DateTimeImmutable()));
225	    }
226	
227	    // Čas přichází zvenku, aby šel v testech zadat.
228	    public function cancel(string $reason, \DateTimeImmutable $when): void
229	    {
230	        // Opakované storno není chyba volajícího, jen už není co dělat.
231	        if ($this->status === OrderStatus::Cancelled) {
232	            return;
233	        }
234	
235	        // Storno je hrana grafu jako každá jiná: odeslanou ani doručenou
236	        // objednávku zpátky nevrátí.
237	        if (!$this->status->canTransitionTo(OrderStatus::Cancelled)) {
238	            throw InvalidOrderStateTransitionException::cannotTransition(
239	                $this->status->value,
240	                OrderStatus::Cancelled->value,
241	            );
242	        }
243	
244	        $this->status = OrderStatus::Cancelled;
245	        $this->cancellationNote = $reason === '' ? null : $reason;
246	        $this->record(new OrderCancelled($this->id, $this->customerId, $reason, $when));
247	    }
248	
249	    public function isOwnedBy(CustomerId $customerId): bool
250	    {
251	        return $this->customerId->equals($customerId);
252	    }
253	
254	    /** Součet položek před slevou. */
255	    public function totalAmount(): Money
256	    {
257	        $total = Money::zero($this->currency);
258	        foreach ($this->lines as $item) {
259	            $total = $total->add($item->subtotal());
260	        }
261	
262	        return $total;
263	    }
264	
265	    /** Částka, kterou zákazník platí: součet položek po slevě. */
266	    public function paidAmount(): Money
267	    {
268	        return $this->totalAmount()
269	            ->subtract($this->discount);
270	    }
271	
272	    private function itemFor(ProductId $productId): OrderItem
273	    {
274	        foreach ($this->lines as $item) {
275	            if ($item->productId->equals($productId)) {
276	                return $item;
277	            }
278	        }
279	
280	        throw OrderItemNotFoundException::forProduct($productId);
281	    }
282	
283	    private function assertSameCurrency(Money $amount): void
284	    {
285	        if ($amount->currency !== $this->currency) {
286	            throw CurrencyMismatchException::forOrder($this->currency, $amount->currency);
287	        }
288	    }
289	}
