5	namespace App\Ordering\Domain\ValueObject;
6	
7	enum OrderStatus: string
8	{
9	    case Draft = 'draft';
10	    case Confirmed = 'confirmed';
11	    case Paid = 'paid';
12	    case Shipped = 'shipped';
13	    case Delivered = 'delivered';
14	    case Cancelled = 'cancelled';
15	
16	    /**
17	     * Stavy, do kterých jde z aktuálního stavu přejít.
18	     *
19	     * @return list<self>
20	     */
21	    public function allowedTransitions(): array
22	    {
23	        return match ($this) {
24	            self::Draft => [self::Confirmed, self::Cancelled],
25	            self::Confirmed => [self::Paid, self::Cancelled],
26	            self::Paid => [self::Shipped, self::Cancelled],
27	            // Odeslanou zásilku storno nevrátí.
28	            self::Shipped => [self::Delivered],
29	            self::Delivered, self::Cancelled => [],
30	        };
31	    }
32	
33	    public function canTransitionTo(self $target): bool
34	    {
35	        return in_array($target, $this->allowedTransitions(), true);
36	    }
37	}
